import pytest
from sample_projects.mini_pos.billing import apply_discount

def test_apply_discount_premium():
    assert apply_discount(1000, "premium") == 900

def test_apply_discount_regular():
    assert apply_discount(1000, "regular") == 1000

def test_apply_discount_zero_total():
    assert apply_discount(0, "premium") == 0

def test_apply_discount_negative_total():
    # Assuming the function does not guard against negative totals
    assert apply_discount(-500, "premium") == -450

import pytest
from sample_projects.mini_pos.billing import checkout

@pytest.mark.parametrize("price,quantity,customer_type,expected", [
    (10, 5, "premium", 45.0),   # 10*5=50, 10% off => 45
    (20, 3, "regular", 60),    # no discount
    (0.99, 100, "premium", 89.1), # 0.99*100=99, 10% off => 89.1
    (1e6, 2, "premium", 1.8e6), # large numbers
])
def test_checkout_various(price, quantity, customer_type, expected):
    assert checkout(price, quantity, customer_type) == expected

