import pytest
from sample_projects.mini_pos.reports import generate_sales_report

@pytest.mark.parametrize("price,quantity,customer_type,expected", [
    (15, 2, "premium", 27.0),   # 15*2=30, 10% off => 27
    (15, 2, "regular", 30),
])
def test_generate_sales_report(price, quantity, customer_type, expected):
    result = generate_sales_report(price, quantity, customer_type)
    assert isinstance(result, dict)
    assert result.get("total_sales") == expected
